let texto = '';
const citas = [];

for (const block of blocks) {
  if (block.type === 'text') {
    texto += block.text;
    if (block.citations) {
      for (const c of block.citations) {
        citas.push({
          texto_citado: c.cited_text,
          documento: c.document_title || c.document_index
        });
      }
