// Autores conocidos en el corpus (Files API) — LACAN·LAB
const autoresConocidos = [
  "lacan", "miller", "freud", "bassols", "schejtman", "campolongo"
];

// Patrones típicos de una afirmación a verificar
const patronesVerificacion = [
  /es cierto que/i,
  /es verdad que/i,
  /confirmá si/i,
  /confirmar si/i,
  /verificá si/i,
  /verificar si/i,
  /¿(es|fue|dijo|planteó|sostuvo)\b.*\?/i,
  /según (lacan|freud|miller|bassols|schejtman|campolongo)/i
];

const pregunta = $input.first().json.pregunta || "";
const preguntaLower = pregunta.toLowerCase();

// Contar cuántos autores conocidos aparecen mencionados
const autoresDetectados = autoresConocidos.filter(autor =>
  preguntaLower.includes(autor)
);

const dos_autores_detectados = autoresDetectados.length >= 2;
const patron_verificacion_detectado = patronesVerificacion.some(regex =>
  regex.test(pregunta)
);

return [{
  json: {
    ...$input.first().json,
    dos_autores_detectados,
    patron_verificacion_detectado,
    autores_detectados: autoresDetectados
