const corpus = [
  { titulo: 'Bassols',     file_id: 'file_01MqRE2T9LBdCHTjDZnoz92k' },
  { titulo: 'Schejtman',   file_id: 'file_011uSGPHuArdMvxRyvRKp8Tg' },
  { titulo: 'Campolongo',  file_id: 'file_011tueMq3JeaMXfow7GfjjVS' },
  { titulo: 'Freud Padre', file_id: 'file_013U9CkbvDzXqhBGT92X2YfZ' }
];

const deteccion = $('Code in JavaScript1').item.json;
const autores = deteccion.autores_detectados || [];
const [autorA, autorB] = autores;

function buscarDocumento(nombreAutor) {
  if (!nombreAutor) return null;
  const norm = nombreAutor.toLowerCase();
  return corpus.find(doc => doc.titulo.toLowerCase().includes(norm)) || null;
}

const docA = buscarDocumento(autorA);
const docB = buscarDocumento(autorB);
const encontrados = [docA, docB].filter(Boolean);
const faltantes = [autorA, autorB].filter((_, i) => ![docA, docB][i]);

const documentos_comparador = encontrados.map(doc => ({
  type: "document",
  source: { type: "file", file_id: doc.file_id },
  title: doc.titulo,
  citations: { enabled: true }
}));

return [{
  json: {
    ...deteccion,
    documentos_comparador,
    autor_a_encontrado: !!docA,
    autor_b_encontrado: !!docB,
    autores_faltantes: faltantes
  }
}];

