  "max_tokens": 1024,
  "system": "Sos un asistente especializado en comparar la obra de dos autores lacanianos a partir EXCLUSIVAMENTE de los documentos adjuntos. Reglas estrictas: (1) NUNCA atribuyas una idea, cita o formulación a un autor si no aparece literalmente en SU documento correspondiente — la atribución cruzada entre autores es el error más grave que podés cometer. (2) Si un concepto aparece en un solo documento y no en el otro, decilo explícitamente en vez de inferir que el segundo autor 'probablemente coincide'. (3) Estructurá la respuesta en exactamente tres secciones: Coincidencias, Diferencias, Evolución del concepto (si aplica). (4) Máximo 250 palabras en total. (5) Devolvé ÚNICAMENTE un JSON válido, sin texto adicional antes o después, con esta forma exacta: { \"respuesta_texto\": string, \"citas\": [ { \"autor\": string, \"documento\": string, \"cita\": string } ], \"tipo\": \"comparacion\", \"autor_a_encontrado\": boolean, \"autor_b_encontrado\": boolean }",
  "messages": [
    {
      "role": "user",
      "content": {{ JSON.stringify([...$json.documentos_comparador, { type: "text", text: $json.pregunta }]) }}
    }
  ]
}

parameters.jsCode:
const respuestaClaude = $input.item.json;

let textoCrudo = '';
try {
  textoCrudo = respuestaClaude.content?.[0]?.text || '';
} catch (e) {
  textoCrudo = '';
}

function limpiarFences(texto) {
  return texto
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/, '')
    .replace(/```\s*$/, '')
    .trim();
}

const textoLimpio = limpiarFences(textoCrudo);
const original = $('Filtrar documentos - Comparador').item.json;

let parsed;
let parseoExitoso = true;

try {
  parsed = JSON.parse(textoLimpio);
} catch (e) {
  parseoExitoso = false;
  parsed = {
    respuesta_texto: textoCrudo || 'Error: no se pudo parsear la respuesta de Claude.',
    citas: [],
    tipo: 'comparacion'
  };
}

return [{
  json: {
    pregunta: original.pregunta,
    autores_detectados: original.autores_detectados,
    autores_faltantes: original.autores_faltantes || [],

    respuesta_texto: parsed.respuesta_texto ?? '',
    citas: parsed.citas ?? [],
    tipo: parsed.tipo ?? 'comparacion',

    autor_a_encontrado: original.autor_a_encontrado ?? false,
    autor_b_encontrado: original.autor_b_encontrado ?? false,

    concepto_encontrado_autor_a: parsed.autor_a_encontrado ?? null,
    concepto_encontrado_autor_b: parsed.autor_b_encontrado ?? null,

    parseo_exitoso: parseoExitoso,
    raw_response_debug: parseoExitoso ? undefined : textoCrudo,

    es_paralelo: !!(original.dos_autores_detectados && original.patron_verificacion_detectado)
  }
}];

const data = $input.item.json;

const autoresDetectados = data.autores_detectados || [];
let documentosFiltrados;
let autorObjetivo = null;
let autorEncontrado = null; // null = no aplica (fallback, sin autor detectado)

if (autoresDetectados.length === 1) {
  autorObjetivo = autoresDetectados[0];
  documentosFiltrados = data.documentos.filter(
    doc => doc.title.toLowerCase() === autorObjetivo.toLowerCase()
  );
  autorEncontrado = documentosFiltrados.length > 0;
} else {
  documentosFiltrados = data.documentos;
}

return {
  json: {
    pregunta: data.pregunta,
    documentos: documentosFiltrados,
    autor_objetivo: autorObjetivo,
    autor_encontrado: autorEncontrado,
    dos_autores_detectados: data.dos_autores_detectados,
    patron_verificacion_detectado: data.patron_verificacion_detectado
  }
};

