const respuestaClaude = $input.item.json.content[0].text;
const previos = $('Filtrar documentos - Verificador').item.json;

let texto = respuestaClaude.trim()
  .replace(/^```json\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(texto);
} catch (e) {
  parsed = {
    veredicto: 'NO_ENCONTRADO',
    respuesta_texto: respuestaClaude,
    citas: [],
    error_parseo: true
  };
}

return {
  json: {
    pregunta: previos.pregunta,
    autor_objetivo: previos.autor_objetivo,
    autor_encontrado: previos.autor_encontrado,
    veredicto: parsed.veredicto,
    respuesta_texto: parsed.respuesta_texto,
    citas: parsed.citas || [],
    tipo: 'verificacion',
    es_paralelo: !!(previos.dos_autores_detectados && previos.patron_verificacion_detectado)
  }
};

const verificador = $('Extraer respuesta Verificador').item.json;
const comparador = $('Extraer respuesta Comparador').item.json;

return [{
  json: {
    pregunta: verificador.pregunta || comparador.pregunta,
    tipo: 'paralelo',

    // Verificación
    autor_objetivo: verificador.autor_objetivo,
    autor_encontrado: verificador.autor_encontrado,
    veredicto: verificador.veredicto,
    respuesta_verificacion: verificador.respuesta_texto,
    citas_verificacion: verificador.citas || [],

    // Comparación
    autores_detectados: comparador.autores_detectados,
    autores_faltantes: comparador.autores_faltantes || [],
    respuesta_comparacion: comparador.respuesta_texto,
    citas_comparacion: comparador.citas || [],
    autor_a_encontrado: comparador.autor_a_encontrado,
    autor_b_encontrado: comparador.autor_b_encontrado
  }
}];
